async function handleSlashSecurityReview(sc: SlashContext): Promise<void> {
  const { rest } = sc;
  await withDetachedRepl(async () => {
    const { securityReviewCommand } = require('../../commands/security-review');
    await securityReviewCommand({ base: rest[0] });
  });
}

async function handleSlashVerbose(sc: SlashContext): Promise<void> {
  const { rest } = sc;
  // Toggle verbose mode (show/hide tool call cards in the message list).
  const { loadSettings: _ls, saveSettings: _ss } = require('../settings');
  const _sv = _ls();
  const _arg = (rest[0] || '').toLowerCase().trim();
  let _nextVerbose: boolean;
  if (_arg === 'on')       _nextVerbose = true;
  else if (_arg === 'off') _nextVerbose = false;
  else                     _nextVerbose = !(_sv.verbose ?? false);
  _ss({ verbose: _nextVerbose });
  const { tuiLog } = require('../tui/bridge');
  if (_nextVerbose) {
    tuiLog('verbose on — tool call cards visible', 'info');
  } else {
    tuiLog('verbose off — tool names shown in status line only', 'info');
  }
}

async function handleSlashVerify(sc: SlashContext): Promise<void> {
  const { rest } = sc;
  // Toggle the auto-verify subagent that runs after edit turns.
  // Default is OFF — opt in with /verify on.
  // Accepts: /verify, /verify on, /verify off
  const { loadSettings, saveSettings } = require('../settings');
  const s = loadSettings() || {};
  const currentlyEnabled = s.autoVerifyEnabled === true
    || (s.autoVerifyDisabled === false && s.autoVerifyEnabled === undefined);
  const arg = (rest[0] || '').toLowerCase().trim();
  let nextEnabled: boolean;
  if (arg === 'on')       nextEnabled = true;
  else if (arg === 'off') nextEnabled = false;
  else                    nextEnabled = !currentlyEnabled;
  // Write the new field and clear the deprecated one to keep
  // settings.json single-sourced.
  saveSettings({ autoVerifyEnabled: nextEnabled, autoVerifyDisabled: undefined });
  const statusWord = nextEnabled ? cyan('ON') : dim('off');
  console.log(`  ${green('✓')} Auto-verify: ${statusWord}`);
  console.log(`  ${dim('(after any turn with edits, a read-only subagent runs builds/tests/probes and reports PASS/FAIL/PARTIAL. Default off — opt in only when you need the safety net.)')}`);
}

async function handleSlashFeedback(sc: SlashContext): Promise<void> {
  const { ctx, rest } = sc;
  const message = rest.join(' ').trim();
  if (!message) { console.log(`  ${dim('Usage: /feedback <message>')}`); return; }
  const feedbackFile = path.join(os.homedir(), '.makestudio', 'feedback.log');
  try {
    fs.mkdirSync(path.dirname(feedbackFile), { recursive: true });
    const entry = {
      timestamp: new Date().toISOString(),
      user: ctx.user?.email,
      cwd: ctx.cwd,
      version: (() => { try { return require('../../package.json').version; } catch { return '?'; } })(),
      message,
    };
    fs.appendFileSync(feedbackFile, JSON.stringify(entry) + '\n', 'utf8');
    // Also try to send to backend (best effort)
    try {
      const { getApiClient } = require('../../network/api-client');
      const api = getApiClient();
      await api.post('/feedback', entry, { timeout: 5_000 }).catch(() => { /* */ });
    } catch (err) { swallow(err); }
    console.log(`  ${green('✓')} Feedback recorded (${feedbackFile})`);
  } catch (err: any) {
    console.log(`  ${yellow('!')} Failed: ${err.message}`);
  }
}

async function handleSlashLogin(sc: SlashContext): Promise<void> {
  const { ctx } = sc;
  // Use the TUI input box for prompts (askTuiOrReadline routes through
  // pendingQuestion when the bridge is installed). NO withDetachedRepl —
  // unmounting Ink mid-command races with raw-mode reset and made Enter
  // print as ^M. Staying inside the TUI is the simpler + correct path.
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { loginCommand } = require('../../commands/login');
    await loginCommand({});
    await ctx.initialize();
    if ((ctx as any).sessionKeyInjected) {
      const info = (ctx as any).providerInfo;
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const { tuiLog } = require('../tui/bridge');
      tuiLog(`✓ session key injected — direct LLM: ${info?.provider}/${info?.model}`, 'info');
    } else {
      const reason = (ctx as any).sessionKeyError || 'unknown';
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const { tuiLog } = require('../tui/bridge');
      tuiLog(`Session key NOT injected — chat will refuse to start. Reason: ${reason}`, 'warn');
    }
  } catch (err: any) {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { tuiLog } = require('../tui/bridge');
    tuiLog(`Login falhou: ${err?.message || err}`, 'error');
  }
}

async function handleSlashHooks(sc: SlashContext): Promise<void> {
  const { ctx, rest, command, cmd } = sc;
  const sub = rest[0]?.toLowerCase();
  // /hooks status — list async hooks currently in flight (PID, event, command, age).
  if (sub === 'status') {
    const { listAsyncHooks } = require('../hooks');
    const inFlight = listAsyncHooks();
    console.log();
    console.log(`  ${chalk.white.bold('Async hooks em execução')}`);
    console.log();
    if (inFlight.length === 0) {
      console.log(`  ${dim('Nenhum async hook rodando.')}`);
    } else {
      for (const h of inFlight) {
        const ageMs = Date.now() - h.startedAt;
        const age = ageMs < 1000 ? `${ageMs}ms` : `${(ageMs / 1000).toFixed(1)}s`;
        console.log(`  ${cyan(`pid ${h.pid}`)} ${dim(h.event)} ${dim(`(${age})`)}: ${h.command}`);
      }
    }
    console.log();
    return;
  }
  const { loadHooks } = require('../hooks');
  const hooks = loadHooks(ctx.activeProject?.localPath || ctx.cwd);
  console.log();
  console.log(`  ${chalk.white.bold('Hooks configurados')}`);
  console.log();
  const events = Object.keys(hooks);
  if (events.length === 0) {
    console.log(`  ${dim('Nenhum hook. Crie em:')}`);
    console.log(`  ${cyan('~/.makestudio/hooks.json')} ${dim('(global)')}`);
    console.log(`  ${cyan('.makestudio/hooks.json')} ${dim('(projeto)')}`);
    console.log();
    console.log(`  ${dim('Exemplo:')}`);
    console.log(`  ${dim('{ "pre-commit": ["npm run lint"], "post-task": ["fvm dart analyze"] }')}`);
  } else {
    for (const event of events) {
      console.log(`  ${cyan(event)}:`);
      for (const cmd of hooks[event]) console.log(`    ${dim('·')} ${cmd}`);
    }
  }
  console.log();
  console.log(`  ${dim('Use')} ${cyan('/hooks status')} ${dim('para ver async hooks rodando.')}`);
  console.log();
}

