async function handleSlashSandbox(sc: SlashContext): Promise<void> {
  const { detectSandboxBackend } = require('../sandbox');
  const backend = detectSandboxBackend();
  console.log();
  console.log(`  ${chalk.white.bold('Sandbox status')}`);
  console.log();
  console.log(`  ${dim('Platform:')}  ${cyan(process.platform)}`);
  console.log(`  ${dim('Backend:')}   ${backend === 'none' ? yellow(backend) : green(backend)}`);
  if (backend === 'none') {
    if (process.platform === 'linux') {
      console.log(`  ${yellow('!')} bwrap nao instalado. Instale: ${cyan('sudo apt install bubblewrap')} ou ${cyan('brew install bubblewrap')}`);
    } else if (process.platform === 'darwin') {
      console.log(`  ${yellow('!')} sandbox-exec deveria estar disponivel no macOS.`);
    } else {
      console.log(`  ${yellow('!')} Plataforma ${process.platform} nao tem backend de sandbox suportado.`);
    }
  } else {
    console.log(`  ${green('✓')} shell_run usa sandbox automaticamente.`);
    console.log(`  ${dim('Levels:')} readonly (safe cmds) · project (default) · full (opt-in) · none (disabled)`);
  }
  console.log();
}

async function handleSlashPermissions(sc: SlashContext): Promise<void> {
  const { ctx, command, cmd } = sc;
  const { loadPolicy } = require('../permissions');
  const policy = loadPolicy(ctx.activeProject?.localPath || ctx.cwd);
  console.log();
  console.log(`  ${chalk.white.bold('Permissions policy')}`);
  console.log();
  console.log(`  ${dim('Default:')} ${cyan(policy.policy)}`);
  if (policy.rules.length === 0) {
    console.log(`  ${dim('Nenhuma regra definida.')}`);
    console.log();
    console.log(`  ${dim('Crie em')} ${cyan('~/.makestudio/permissions.json')} ${dim('ou')} ${cyan('.makestudio/permissions.json')}`);
    console.log(`  ${dim('Exemplo:')}`);
    console.log(`  ${dim('{ "policy": "ask", "rules": [')}`);
    console.log(`  ${dim('   { "tool": "shell_run", "command": "npm *", "action": "allow" },')}`);
    console.log(`  ${dim('   { "tool": "shell_run", "command": "rm *", "action": "deny"  }')}`);
    console.log(`  ${dim(']}')}`);
  } else {
    console.log(`  ${dim('Rules (order matters, first match wins):')}`);
    for (const r of policy.rules) {
      const parts: string[] = [cyan(r.tool)];
      if (r.command) parts.push(dim('cmd=' + r.command));
      if (r.pathPrefix) parts.push(dim('path=' + r.pathPrefix));
      if (r.domain) parts.push(dim('domain=' + r.domain));
      const color = r.action === 'allow' ? green : r.action === 'deny' ? chalk.hex('#EF4444') : yellow;
      console.log(`    ${color(r.action.padEnd(5))} ${parts.join(' ')}`);
    }
  }
  console.log();
}

async function handleSlashTrust(sc: SlashContext): Promise<void> {
  const { ctx, rest } = sc;
  const action = rest[0]?.toLowerCase();
  if (action === 'on' || action === 'all') {
    ctx.autoApprove = true;
    console.log(`  ${green('✓')} Modo confiável ATIVADO — IA pode usar tools sensíveis sem confirmação.`);
  } else if (action === 'off') {
    ctx.autoApprove = false;
    ctx.approvedTools.clear();
    console.log(`  ${yellow('!')} Modo confiável DESATIVADO — confirmação será pedida.`);
  } else {
    // Single multi-line console.log — the bridge collapses each console.log
    // into one info bubble; sending three separate calls produced three
    // stacked single-liners with their own info icon. One block = one card.
    const status = ctx.autoApprove ? green('confiável (sem confirmação)') : cyan('pedindo confirmação');
    const approved = [...ctx.approvedTools].join(', ') || dim('(nenhuma)');
    const lines = [
      `  ${bold('/trust')} ${dim('— modo de confiança da sessão')}`,
      `  ${dim('estado:')}    ${status}`,
      `  ${dim('aprovadas:')} ${approved}`,
      `  ${dim('uso:')}       ${cyan('/trust on')}  ${dim('|')}  ${cyan('/trust off')}`,
      `  ${dim('persistente:')} use ${cyan('/permission-mode bypassPermissions')} pra que valha entre sessões`,
    ];
    console.log(lines.join('\n'));
  }
}

async function handleSlashDebug(sc: SlashContext): Promise<void> {
  const { ctx, rest, input } = sc;
  const subCmd = rest[0]?.toLowerCase();
  let dbgMod: any = null;
  try { dbgMod = require('../debug-log'); } catch (err) { swallow(err); }

  // /debug log — show audit log path and toggle
  if (subCmd === 'log' || subCmd === 'on' || subCmd === 'off') {
    console.log();
    if (subCmd === 'on') {
      dbgMod?.enableDebugLog();
      const p = dbgMod?.getDebugLogPath();
      console.log(`  ${green('debug log on')}${p ? '  →  ' + dim(p) : ''}`);
    } else if (subCmd === 'off') {
      dbgMod?.disableDebugLog();
      console.log(`  ${dim('debug log off')}`);
    } else {
      const enabled = dbgMod?.isDebugEnabled() ?? false;
      const p = dbgMod?.getDebugLogPath();
      console.log(`  ${dim('Debug log:')} ${enabled ? green('on') : dim('off')}`);
      if (p) console.log(`  ${dim('Log path:')}  ${cyan(p)}`);
      else   console.log(`  ${dim('Start with')} ${cyan('makestudio --debug')} ${dim('or')} ${cyan('/debug on')} ${dim('to activate')}`);
      console.log();
      console.log(`  ${dim('/debug on')}   — ativa log desta sessao`);
      console.log(`  ${dim('/debug off')}  — desativa`);
      console.log(`  ${dim('makestudio --debug')}  — ativa automaticamente`);
      console.log(`  ${dim('DEBUG=1 makestudio')}  — mesmo efeito via env`);
    }
    console.log();
    return;
  }

  // default: show last tool call (original behavior)
  const last = ctx.lastToolCall;
  console.log();
  if (!last) {
    console.log(`  ${dim('Nenhuma tool call nesta sessao ainda.')}`);
    const p = dbgMod?.getDebugLogPath();
    if (p) console.log(`  ${dim('Audit log ativo:')} ${cyan(p)}`);
    else   console.log(`  ${dim('Use')} ${cyan('/debug log')} ${dim('para ver o audit trail completo')}`);
    console.log();
    return;
  }
  console.log(`  ${chalk.white.bold('Ultima Tool Call')}`);
  console.log();
  console.log(`  ${dim('Tool:')}      ${cyan(last.name)}`);
  console.log(`  ${dim('Quando:')}    ${dim(new Date(last.timestamp).toLocaleString('pt-BR'))}`);
  console.log(`  ${dim('Duracao:')}   ${green(last.durationMs + 'ms')}`);
  console.log(`  ${dim('Input:')}`);
  console.log(JSON.stringify(last.input, null, 2).split('\n').map(l => '    ' + l).join('\n'));
  console.log(`  ${dim('Output:')}`);
  const out = last.output.length > 2000 ? last.output.slice(0, 2000) + `\n... [+${last.output.length - 2000} chars]` : last.output;
  console.log(out.split('\n').map(l => '    ' + l).join('\n'));
  const p2 = dbgMod?.getDebugLogPath();
  if (p2) console.log(`\n  ${dim('Audit log completo:')} ${cyan(p2)}`);
  console.log();
}


